package e2e

import (
	"encoding/json"
	"os"
	"path/filepath"
	"testing"

	"github.com/sloprail/sloprail/tests/e2e/harness"
)

// trajectory describe — facts ABOUT a trajectory: whether it belongs to a
// sub-agent, which trajectory spawned it, and which it spawned. These tests
// exercise the COMPILED sr-session binary as a subprocess against trajectories
// the MOCK produced, asserting the JSON on stdout.
//
// # Where the trajectories come from
//
// The trajectory a `describe` reads is generated by driving a10n-claude-mock
// through the harness — the same drop-in `claude` the rest of the e2e uses — and
// then handing `describe --path` the record the mock wrote. A dispatch turn makes
// the mock write a real sub-agent record under <session>/subagents/, with the
// isSidechain origin and the agent-<id>.meta.json companion Claude Code writes.
// So the shapes describe classifies are the mock's, deterministic and centralised,
// not a Claude Code record shape re-typed by hand in this file.
//
// # The one shape the mock cannot produce, and why a fixture stays
//
// The parent correlation (T028_02) is the exception, and it is a MEASURED limit
// of the mock rather than a preference. describe derives a sub-agent's parentPath
// from the toolUseId its meta file records — the id of the dispatching tool_use in
// the parent — and the mock writes that field EMPTY for every sub-agent it seeds
// (verified in a10n-cli's claude-mock: seedSubagentTranscript hardcodes
// `"toolUseId": ""`, and the engine names the mock explicitly in
// internal/transcript/describe.go's ParentPath). A mock-driven sub-agent is
// therefore exactly the T028_03 shape — isSubagent true, no parent derivable — and
// the ONLY way to exercise a derivable parent is a record carrying the toolUseId
// Claude Code actually writes. That is the single hand-authored fixture below;
// everything else reads a mock-produced transcript.

type Env = harness.Env

var (
	New      = harness.New
	Turns    = harness.Turns
	Bash     = harness.Bash
	Dispatch = harness.Dispatch
)

// TestMain removes the binary build dir when this package's tests finish.
func TestMain(m *testing.M) {
	code := m.Run()
	harness.Cleanup()
	os.Exit(code)
}

// writeScenario renders a scenario to a script the mock runs as a sub-agent, and
// returns its path — how a dispatch turn is given the behaviour its sub-agent runs.
func writeScenario(t *testing.T, proj string, s harness.Scenario) string {
	t.Helper()
	path := filepath.Join(proj, "sub.sh")
	if err := s.Script(path); err != nil {
		t.Fatalf("write sub-agent scenario: %v", err)
	}
	return path
}

// --- the one hand-authored fixture: a sub-agent whose meta names its dispatching
// tool_use, which the mock cannot write (see the package note). ---

// fixtureParent is a project directory holding a hand-authored root transcript and
// a sub-agent record whose meta carries a real toolUseId — the parent correlation
// the mock leaves underivable. Kept minimal: only the two records the correlation
// walks, and only the fields it reads.
type fixtureParent struct {
	t   *testing.T
	dir string
}

func newFixtureParent(t *testing.T) *fixtureParent {
	t.Helper()
	dir, err := os.MkdirTemp("", "traj-parent-")
	if err != nil {
		t.Fatalf("temp project: %v", err)
	}
	t.Cleanup(func() { os.RemoveAll(dir) })
	return &fixtureParent{t: t, dir: dir}
}

// root writes the root transcript at <dir>/<session>.jsonl: a parentless origin and
// an assistant turn dispatching a sub-agent by toolUseID — the id the sub-agent's
// meta points back at.
func (f *fixtureParent) root(session, toolUseID string) string {
	f.t.Helper()
	origin := `{"type":"user","uuid":"root-origin","parentUuid":null,"isSidechain":false,` +
		`"message":{"role":"user","content":"start the work"}}`
	dispatch := `{"type":"assistant","uuid":"root-dispatch","parentUuid":"root-origin","isSidechain":false,` +
		`"message":{"role":"assistant","content":[{"type":"text","text":"delegating"},` +
		`{"type":"tool_use","id":"` + toolUseID + `","name":"Agent","input":{"description":"go"}}]}}`
	return writeLines(f.t, filepath.Join(f.dir, session+".jsonl"), origin, dispatch)
}

// subagent writes a sub-agent record and its meta companion under
// <dir>/<session>/subagents/, the meta naming toolUseID so the parent is derivable.
func (f *fixtureParent) subagent(session, agentID, toolUseID string) string {
	f.t.Helper()
	dir := filepath.Join(f.dir, session, "subagents")
	if err := os.MkdirAll(dir, 0o755); err != nil {
		f.t.Fatalf("mkdir subagents: %v", err)
	}
	origin := `{"type":"user","uuid":"sub-origin","parentUuid":null,"isSidechain":true,` +
		`"agentId":"` + agentID + `","message":{"role":"user","content":"do the delegated thing"}}`
	path := writeLines(f.t, filepath.Join(dir, "agent-"+agentID+".jsonl"), origin)

	meta := map[string]any{
		"agentType": "Explore", "description": "look into X", "toolUseId": toolUseID, "spawnDepth": 1,
	}
	b, err := json.Marshal(meta)
	if err != nil {
		f.t.Fatalf("marshal meta: %v", err)
	}
	if err := os.WriteFile(filepath.Join(dir, "agent-"+agentID+".meta.json"), b, 0o644); err != nil {
		f.t.Fatalf("write meta: %v", err)
	}
	return path
}

func writeLines(t *testing.T, path string, lines ...string) string {
	t.Helper()
	body := ""
	for _, l := range lines {
		body += l + "\n"
	}
	if err := os.WriteFile(path, []byte(body), 0o644); err != nil {
		t.Fatalf("write %s: %v", path, err)
	}
	return path
}

// decodeDescribe parses the describe command's JSON stdout.
func decodeDescribe(t *testing.T, out string) map[string]any {
	t.Helper()
	var m map[string]any
	if err := json.Unmarshal([]byte(out), &m); err != nil {
		t.Fatalf("describe output is not JSON (%v):\n%s", err, out)
	}
	return m
}
